import sqlite3

def get_window2_transcript(c, video_id, duration_seconds):
    w2_start = duration_seconds * 0.30
    w2_end = duration_seconds * 0.60
    rows = c.execute(
        "SELECT start_seconds, text FROM transcript_segments WHERE video_id=? AND start_seconds >= ? AND start_seconds <= ? ORDER BY start_seconds",
        (video_id, w2_start, w2_end)
    ).fetchall()
    
    if not rows:
        rows = c.execute(
            "SELECT start_seconds, text FROM transcript_segments WHERE video_id=? ORDER BY start_seconds LIMIT 25",
            (video_id,)
        ).fetchall()

    paragraphs = []
    chunk = []
    chunk_start = 0
    for r in rows:
        if not chunk:
            chunk_start = r[0]
        chunk.append(r[1].strip())
        if len(chunk) >= 4:
            m, s = divmod(int(chunk_start), 60)
            text = " ".join(chunk)
            # ASR cleaning
            text = text.replace("на уровне кремня", "на уровне кремния")
            text = text.replace("order buks", "order books")
            text = text.replace("coat stuffing", "quote stuffing")
            text = text.replace("хэдж позиция", "хедж-позиция")
            text = text.replace("в 3 ночи", "в 3:00 ночи")
            paragraphs.append(f"[{m:02d}:{s:02d}] {text}")
            chunk = []
    if chunk:
        m, s = divmod(int(chunk_start), 60)
        text = " ".join(chunk)
        text = text.replace("на уровне кремня", "на уровне кремния")
        text = text.replace("order buks", "order books")
        text = text.replace("coat stuffing", "quote stuffing")
        text = text.replace("хэдж позиция", "хедж-позиция")
        text = text.replace("в 3 ночи", "в 3:00 ночи")
        paragraphs.append(f"[{m:02d}:{s:02d}] {text}")
    return paragraphs

